//! Embedded generic x64 gbe_fork `load_dlls` stub DLLs (Steamworks stubs, identical for
//! every game — the same pair the DiscordActivator skeleton ships). Stored gzip+base64 as
//! source text so no standalone `.dll` sits in the repo for antivirus to delete. Decoded on
//! demand by [`load_dll_stubs`]. To regenerate if the stub pair ever changes, gzip each DLL and
//! base64-encode it into the two consts below (kept as text so no `.dll` lands in the repo tree).

use std::io::Read;

use base64::Engine;

const STEAM_STUBBED_GZ_B64: &str = "";
const STUB_GZ_B64: &str = "";

fn inflate(b64: &str) -> Vec<u8> {
    let compressed = base64::engine::general_purpose::STANDARD
        .decode(b64)
        .expect("embedded load_dll base64");
    let mut out = Vec::new();
    flate2::read::GzDecoder::new(std::io::Cursor::new(compressed))
        .read_to_end(&mut out)
        .expect("embedded load_dll gzip");
    out
}

/// The generic x64 `load_dlls` stub DLLs as `(file name, bytes)`, decoded from the embedded
/// blobs. These are x64-only, so callers add them only for x64 deploys.
#[must_use]
pub fn load_dll_stubs() -> Vec<(&'static str, Vec<u8>)> {
    vec![
        ("steam_stubbed.dll", inflate(STEAM_STUBBED_GZ_B64)),
        ("stub.dll", inflate(STUB_GZ_B64)),
    ]
}
